534	type parsedBlock struct {
535		line  int
536		block Block
537	}
538	
539	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
540		var out []parsedBlock
541		reader := bufio.NewReader(r)
542		lineNo := 0
543		for {
544			raw, err := reader.ReadBytes('\n')
545			if len(raw) > 0 {
546				lineNo++
547			}
548			if text := strings.TrimSpace(string(raw)); text != "" {
549				block, perr := parseBlock(text)
550				if perr != nil {
551					return nil, &LineError{Line: lineNo, Err: perr}
552				}
553				out = append(out, parsedBlock{line: lineNo, block: block})
554			}
555			if err == io.EOF {
556				return out, nil
557			}
558			if err != nil {
559				return nil, err
560			}
561		}
562	}
