564	// ReplayFile imports the line-delimited blocks in inputPath into the
565	// archive at dir and returns one report per distinct block, in order of
566	// first appearance. New blocks are judged under the archive's currently
567	// enabled rule version; that version's stored document must still satisfy
568	// the registration rules in full, or the whole replay fails with
569	// ErrCorruptVersion before any report is produced.
570	func ReplayFile(inputPath, dir string) ([]Report, error) {
571		return replayFile(inputPath, dir, "")
572	}
573	
574	// ReplayFileWithVersion is ReplayFile under an explicitly registered rule
575	// version instead of the archive's enabled one. The named version's stored
576	// document must still satisfy the registration rules in full; a corrupt
577	// one fails the whole replay with ErrCorruptVersion rather than judging
578	// under zeroed or substituted parameters.
579	func ReplayFileWithVersion(inputPath, dir, versionID string) ([]Report, error) {
580		if versionID == "" {
581			return nil, errors.New("version id must not be empty")
582		}
583		return replayFile(inputPath, dir, versionID)
584	}
585	
586	func replayFile(inputPath, dir, versionID string) ([]Report, error) {
587		f, err := os.Open(inputPath)
588		if err != nil {
589			return nil, err
590		}
591		defer f.Close()
592		return doReplay(f, dir, versionID)
593	}
594	
595	// Replay parses, validates and archives blocks from r under the archive's
596	// currently enabled rule version. Every line is checked before anything is
597	// written; any failure leaves the archive untouched. New reports are
598	// committed together in a single atomic write. The selected version's
599	// stored document is re-validated before any block is judged: a corrupt
600	// version fails the whole replay with ErrCorruptVersion — never a
601	// substituted or zeroed parameter set — even when no input block would
602	// have triggered the damaged rule.
603	//
604	// A block that is already archived and arrives with identical content is
605	// not re-judged: its original report is returned. Before that report is
606	// returned the declaration the record archived is proved from its raw
607	// bytes by exactly the standard a standalone report query (Query)
608	// enforces — a non-empty id, both rules each declaring a boolean enabled
609	// and an integer severity 1-5, and a displacement multiplier 2-100 —
610	// rather than trusted because this run's own version is legal. A
611	// declaration saved as null, as an empty object, only in part, with a
612	// wrong type or out-of-range number, an unknown rule or field, or a field
613	// repeated in one object (the field-name folding and escapes included,
614	// even when both values agree) fails the whole replay with
615	// ErrCorruptVersion; an explicit enabled:false is a legal off state but a
616	// disabled rule still has to be declared completely. Only a wholly absent
617	// version key — the pre-version legacy shape — is explained by the
618	// built-in rules; a written "builtin" id is validated like every other.
619	// On failure no report is returned, no same-batch new block is saved and
620	// no archived content changes, regardless of where the corrupt old block
621	// sits relative to the new ones. An intact old report is returned with
622	// its originally saved conclusions, evidence, swap count and full
623	// parameters, never re-detected and never completed from the currently
624	// enabled or a same-id registered version; its historical id need not
625	// still be registered.
626	func Replay(input io.Reader, dir string) ([]Report, error) {
627		return doReplay(input, dir, "")
628	}
629	
630	// ReplayWithVersion is Replay under an explicitly registered rule version
631	// instead of the archive's enabled one, with the same integrity check: a
632	// corrupt stored version document fails the whole replay with
633	// ErrCorruptVersion before any report is produced.
634	func ReplayWithVersion(input io.Reader, dir, versionID string) ([]Report, error) {
635		if versionID == "" {
636			return nil, errors.New("version id must not be empty")
637		}
638		return doReplay(input, dir, versionID)
639	}
640	
641	func doReplay(input io.Reader, dir, versionID string) ([]Report, error) {
642		parsed, err := parseBlocks(input)
643		if err != nil {
644			return nil, err
645		}
646	
647		// Collapse repeated identities within this file, keeping first
648		// appearance order; conflicting content rejects the whole file.
649		type occurrence struct {
650			block Block
651			line  int
652		}
653		order := []occurrence{}
654		firstSeen := make(map[blockID]int)
655		for _, p := range parsed {
656			id := blockID{p.block.ChainID, p.block.BlockHash}
657			if first, ok := firstSeen[id]; ok {
658				if !sameContent(order[first].block.BlockNumber, order[first].block.Swaps, p.block) {
659					return nil, &LineError{Line: p.line, Err: fmt.Errorf(
660						"block %s/%s conflicts with line %d", id.chainID, id.blockHash, order[first].line)}
661				}
662				continue
663			}
664			firstSeen[id] = len(order)
665			order = append(order, occurrence{block: p.block, line: p.line})
666		}
667	
668		if err := os.MkdirAll(dir, 0o755); err != nil {
669			return nil, err
670		}
671		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
672		if err != nil {
673			return nil, err
674		}
675		defer lock.Close()
676	
677		// Decode with every stored record and registered version kept as its
678		// raw stored document, so a wrong-typed field in one entry is that
679		// entry's corruption, not whole-archive corruption: the selected
680		// version's document is re-validated from its bytes the same way a
681		// single-block comparison proves its version intact, and each already
682		// archived block this run re-imports is proved from its record's raw
683		// bytes the same way a standalone report query proves it, rather than
684		// decoded into silently zeroed parameters or a null-explained
685		// built-in report.
686		raw, err := readArchiveBytes(dir)
687		if err != nil {
688			return nil, err
689		}
690		data := replayArchiveDoc{Records: []json.RawMessage{}}
691		if raw != nil {
692			if err := json.Unmarshal(raw, &data); err != nil {
693				return nil, fmt.Errorf("archive is corrupted: %w", err)
694			}
695		}
696		// Resolve the version once, while the exclusive lock is held: every
697		// new block in this run is judged under the same rules even if another
698		// process enables a different version right after we finish. The
699		// selected version's stored document must still satisfy the
700		// registration rules in full; a corrupt one fails the whole replay
701		// with ErrCorruptVersion here, before any block is judged, any report
702		// is produced or anything is written — even when the input is empty,
703		// holds only blocks already archived, or would never trigger the
704		// damaged rule. The corrupt content is never replaced by the enabled
705		// version, the built-in rules or defaults.
706		version, err := resolveReplayVersion(data, versionID)
707		if err != nil {
708			return nil, err
709		}
710		// Index the stored records by block identity with their decoded
711		// content; the embedded version stays raw until an identical reimport
712		// actually has to present that record's report, when its saved
713		// declaration is proved exactly as a report query would.
714		stored := make([]queryRecord, len(data.Records))
715		archived := make(map[blockID]int, len(data.Records))
716		for i, rawRec := range data.Records {
717			var qr queryRecord
718			if err := json.Unmarshal(rawRec, &qr); err != nil {
719				return nil, fmt.Errorf("archive is corrupted: record %d: %w", i, err)
720			}
721			stored[i] = qr
722			archived[blockID{qr.ChainID, qr.BlockHash}] = i
723		}
724	
725		reports := make([]Report, 0, len(order))
726		newRecords := []json.RawMessage{}
727		for _, occ := range order {
728			id := blockID{occ.block.ChainID, occ.block.BlockHash}
729			if idx, ok := archived[id]; ok {
730				rec := stored[idx]
731				if !sameContent(rec.BlockNumber, rec.Swaps, occ.block) {
732					return nil, &LineError{Line: occ.line, Err: fmt.Errorf(
733						"block %s/%s conflicts with the archived record", id.chainID, id.blockHash)}
734				}
735				// Identical re-import: return the original report, add nothing.
736				// The saved declaration is held to the standard of a standalone
737				// report query before any conclusion is returned — never read as
738				// built-in from a null version or as zeroed parameters from an
739				// incomplete one, and never completed from the version this run
740				// selected. A corrupt declaration fails the whole batch here,
741				// before a single new block is committed, whether the old block
742				// appears before or after the new ones.
743				report, perr := reportFromQueryRecord(&rec)
744				if perr != nil {
745					return nil, &LineError{Line: occ.line, Err: perr}
746				}
747				reports = append(reports, report)
748				continue
749			}
750			rec := record{
751				ChainID:     occ.block.ChainID,
752				BlockHash:   occ.block.BlockHash,
753				BlockNumber: occ.block.BlockNumber,
754				Swaps:       occ.block.Swaps,
755				Findings:    DetectBlockWithRules(occ.block.Swaps, version.Rules),
756				Version:     &version,
757			}
758			rawRec, perr := json.Marshal(rec)
759			if perr != nil {
760				return nil, perr
761			}
762			newRecords = append(newRecords, rawRec)
763			reports = append(reports, rec.report())
764		}
765		// All blocks passed — new and identical alike — so commit the new
766		// records once, leaving every stored record's raw bytes untouched.
767		if len(newRecords) > 0 {
768			data.Records = append(data.Records, newRecords...)
769			if err := writeArchiveAtomic(dir, data); err != nil {
770				return nil, err
771			}
772		}
773		return reports, nil
774	}
775	
776	// resolveReplayVersion picks the rule version for one replay run — the
777	// explicitly requested one, or the archive's currently enabled version —
778	// and proves its stored archive document still satisfies every
779	// registration rule, re-validating the raw document with the same parser
780	// registrations pass. The decoded struct cannot do this: a missing
781	// enabled, severity or multiplier field unmarshals as the zero value and
782	// is indistinguishable from an explicitly declared one, and a zero
783	// displacement multiplier even crashes detection. An explicitly declared
784	// false or any in-range value is valid; a missing or null field, a wrong
785	// type or an out-of-range number makes the version corrupt, and the
786	// failure names the version and the offending rule or field. Archives
787	// written before rule versions existed have no enabled marker and run the
788	// built-in rules; the built-in version is constructed in code and always
789	// intact.
790	func resolveReplayVersion(data replayArchiveDoc, versionID string) (RuleVersion, error) {
791		id := versionID
792		if id == "" {
793			id = data.EnabledVersion
794			if id == "" {
795				return BuiltinVersion(), nil
796			}
797		}
798		return intactVersion(data.Versions, id)
799	}
800	
801	// queryArchiveDoc mirrors just the records a report query reads, keeping
802	// each record's embedded version declaration as its raw stored document —
803	// the same shape registered versions are kept in everywhere else — so a
804	// wrong-typed field in one report's declaration fails that report's query
805	// rather than breaking the whole-archive decode or decoding into silently
806	// zeroed parameters.
807	type queryArchiveDoc struct {
808		Records []queryRecord `json:"records"`
809	}
810	
811	// Query returns the archived report for one block identity. It only reads
812	// the archive; the original input file is not needed, and neither a
813	// successful nor a failed query rewrites anything.
814	//
815	// Before the report is returned, the complete version declaration the
816	// report archived is re-validated from its raw bytes with the same proof
817	// registration, enable, comparison, evaluation and replay demand: a
818	// non-empty version identifier, both the sandwich and displacement rules
819	// each with a boolean enabled and an integer severity in 1-5, and the
820	// displacement multiplier an integer in 2-100. A missing or null field or
821	// rule object, a wrong type, an out-of-range number, an unknown field or
822	// rule, or a field declared twice in one object (an exact repeat, an
823	// escaped spelling or a case-only spelling that names the same field —
824	// even when both values agree) makes the saved declaration corrupt. An
825	// explicit enabled:false is a legal off state, not damage; the disabled
826	// rule still has to carry complete, in-range parameters.
827	//
828	// Only an old-format record with no "version" key at all keeps the
829	// original built-in interpretation. A declaration actually saved as null,
830	// as an empty object or only in part is corruption, and an id of
831	// "builtin" is validated like every other id rather than bypassing the
832	// check. On corruption Query fails with ErrCorruptVersion naming the
833	// target chain and block, the readable saved version id and the offending
834	// rule or field; it never zero-fills the parameters, explains them as
835	// built-in, or substitutes parameters from the currently enabled or a
836	// registered version. The report uses the parameters it archived and is
837	// never re-detected. A block that was never archived stays
838	// ErrUnknownBlock.
839	func Query(dir, chainID, blockHash string) (Report, error) {
840		if _, err := os.Stat(dir); err != nil {
841			if errors.Is(err, os.ErrNotExist) {
842				return Report{}, ErrUnknownBlock
843			}
844			return Report{}, err
845		}
846		lock, err := lockArchive(dir, syscall.LOCK_SH)
847		if err != nil {
848			return Report{}, err
849		}
850		defer lock.Close()
851	
852		raw, err := readArchiveBytes(dir)
853		if err != nil {
854			return Report{}, err
855		}
856		var doc queryArchiveDoc
857		if len(raw) > 0 {
858			if err := json.Unmarshal(raw, &doc); err != nil {
859				return Report{}, fmt.Errorf("archive is corrupted: %w", err)
860			}
861		}
862		idx := -1
863		for i := range doc.Records {
864			if doc.Records[i].ChainID == chainID && doc.Records[i].BlockHash == blockHash {
865				idx = i
866				break
867			}
868		}
869		if idx < 0 {
870			return Report{}, ErrUnknownBlock
871		}
872		rec := &doc.Records[idx]
873		return reportFromQueryRecord(rec)
874	}
