package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	mw "github.com/gzhysuiioo/mevwatch-guard/mevwatch"
)

func TestPreserveAlertDeclarations(t *testing.T) {
	dir := t.TempDir()
	// One intact report with a sandwich conclusion to review, plus alert
	// records whose version declarations are damaged in three ways.
	archive := `{"records":[{"chainId":"1","blockHash":"0xa","blockNumber":5,` +
		`"swaps":[` +
		`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
		`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
		`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}],` +
		`"findings":[{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[` +
		`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
		`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
		`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}]}],` +
		`"version":{"id":"builtin","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}}],` +
		`"alerts":[` +
		// version:null
		`{"chainId":"1","blockHash":"0xa","blockNumber":5,"pool":"p1","channel":"ops",` +
		`"finding":{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0}]},` +
		`"version":null,"minSeverity":1,"status":"alert","suppressions":[]},` +
		// incomplete declaration (missing multiplier)
		`{"chainId":"1","blockHash":"0xa","blockNumber":5,"pool":"p1","channel":"ops",` +
		`"finding":{"kind":"displacement","severity":2,"txHash":"0w","evidence":[{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0}]},` +
		`"version":{"id":"v1","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2}}},"minSeverity":1,"status":"suppressed","suppressions":[{"id":"s-1","reason":"maint"}]},` +
		// duplicate severity field with different values
		`{"chainId":"1","blockHash":"0xa","blockNumber":5,"pool":"p1","channel":"ops",` +
		`"finding":{"kind":"sandwich","severity":3,"txHash":"0x","evidence":[{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0}]},` +
		`"version":{"id":"v2","rules":{"sandwich":{"enabled":true,"severity":3,"severity":5},"displacement":{"enabled":true,"severity":2,"multiplier":2}}},"minSeverity":2,"status":"alert","suppressions":[]}` +
		`]}`
	if err := os.WriteFile(filepath.Join(dir, "archive.json"), []byte(archive), 0o644); err != nil {
		t.Fatal(err)
	}
	before, _ := os.ReadFile(filepath.Join(dir, "archive.json"))

	sub := mw.ReviewSubmission{ChainID: "1", BlockHash: "0xa", TxHash: "0v", Kind: "sandwich",
		SubmissionID: "r-1", Operator: "alice", Reason: "confirmed", Status: mw.ReviewStatusReal, ExpectedVersion: 0}
	res, err := mw.SubmitReview(dir, sub)
	if err != nil || !res.Created {
		t.Fatalf("submit = %+v, %v", res, err)
	}
	// rejudgment + withdrawal also append revisions and must preserve too
	sub2 := sub
	sub2.SubmissionID, sub2.ExpectedVersion, sub2.Status = "r-2", 1, mw.ReviewStatusFalsePositive
	if _, err := mw.SubmitReview(dir, sub2); err != nil {
		t.Fatal(err)
	}
	sub3 := sub
	sub3.SubmissionID, sub3.ExpectedVersion, sub3.Status = "r-3", 2, mw.ReviewStatusUnreviewed
	if _, err := mw.SubmitReview(dir, sub3); err != nil {
		t.Fatal(err)
	}

	after, _ := os.ReadFile(filepath.Join(dir, "archive.json"))
	a := string(after)
	for _, want := range []string{
		`"version": null`,                       // null stays null
		`"id": "v1"`,                            // incomplete declaration kept
		`"severity": 3, "severity": 5`,          // duplicate fields, order and values kept
		`"status": "suppressed"`,                // statuses preserved
		`"minSeverity": 2`,                      // thresholds preserved
	} {
		if !strings.Contains(a, want) {
			t.Fatalf("archive lost %q:\n%s", want, a)
		}
	}
	// the incomplete declaration must not have gained a multiplier
	if strings.Contains(a, `"v1"`) && strings.Contains(a[strings.Index(a, `"v1"`):], `multiplier`) {
		if idx := strings.Index(a, `"v1"`); strings.Contains(a[idx:idx+200], "multiplier") {
			t.Fatalf("incomplete declaration was completed:\n%s", a)
		}
	}
	// alert history must still fail on the damaged declarations (not become valid)
	if _, err := mw.AlertHistory(dir, "1", "ops", 0, 100); err == nil {
		t.Fatal("alert history should still fail on damaged declarations")
	}
	// review history shows the new revisions
	h, err := mw.ReviewHistoryQuery(dir, "1", "0xa", "0v", "sandwich")
	if err != nil || h.Version != 3 || len(h.Revisions) != 3 || h.Status != mw.ReviewStatusUnreviewed {
		t.Fatalf("history = %+v, %v", h, err)
	}
	_ = before
